  nn_lowmem: { bg: 'Невронен модел: изключен (малко памет на телефона) — ползва се старото сравнение по отпечатъци.', ru: 'Нейросетевая модель: отключена (мало памяти) — используется старое сравнение по отпечаткам.', uk: 'Нейромережева модель: вимкнена (мало пам’яті) — використовується старе порівняння за відбитками.', en: 'Neural model: off (low phone memory) — the older fingerprint comparison is used.', de: 'Neuronales Modell: aus (wenig Speicher) — der ältere Fingerabdruck-Vergleich wird verwendet.', fr: 'Modèle neuronal : désactivé (mémoire faible) — l’ancienne comparaison par empreintes est utilisée.', es: 'Modelo neuronal: desactivado (poca memoria) — se usa la comparación antigua por huellas.', 'es-MX': 'Modelo neuronal: desactivado (poca memoria) — se usa la comparación antigua por huellas.', it: 'Modello neurale: disattivato (poca memoria) — si usa il vecchio confronto per impronte.', pt: 'Modelo neuronal: desligado (pouca memória) — usa-se a comparação antiga por impressões.', ar: 'النموذج العصبي: معطّل (ذاكرة قليلة) — تُستخدم المقارنة القديمة بالبصمات.', hi: 'न्यूरल मॉडल: बंद (फ़ोन मेमोरी कम) — पुरानी फ़िंगरप्रिंट तुलना उपयोग में है।', ja: 'ニューラルモデル：オフ（端末メモリ不足）— 従来の特徴量比較を使用します。', ky: 'Нейрон модели: өчүк (телефондун эси аз) — эски издер боюнча салыштыруу колдонулат.', 'zh-Hant': '神經網路模型：關閉（手機記憶體不足）— 改用舊的特徵比對。' },
  nn_off: { bg: 'Невронен модел: недостъпен ({e}) — ползва се старото сравнение по отпечатъци.', ru: 'Нейросетевая модель: недоступна ({e}) — используется старое сравнение по отпечаткам.', uk: 'Нейромережева модель: недоступна ({e}) — використовується старе порівняння за відбитками.', en: 'Neural model: unavailable ({e}) — the older fingerprint comparison is used.', de: 'Neuronales Modell: nicht verfügbar ({e}) — der ältere Fingerabdruck-Vergleich wird verwendet.', fr: 'Modèle neuronal : indisponible ({e}) — l’ancienne comparaison par empreintes est utilisée.', es: 'Modelo neuronal: no disponible ({e}) — se usa la comparación antigua por huellas.', 'es-MX': 'Modelo neuronal: no disponible ({e}) — se usa la comparación antigua por huellas.', it: 'Modello neurale: non disponibile ({e}) — si usa il vecchio confronto per impronte.', pt: 'Modelo neuronal: indisponível ({e}) — usa-se a comparação antiga por impressões.', ar: 'النموذج العصبي: غير متاح ({e}) — تُستخدم المقارنة القديمة بالبصمات.', hi: 'न्यूरल मॉडल: उपलब्ध नहीं ({e}) — पुरानी फ़िंगरप्रिंट तुलना उपयोग में है।', ja: 'ニューラルモデル：利用不可（{e}）— 従来の特徴量比較を使用します。', ky: 'Нейрон модели: жеткиликсиз ({e}) — эски издер боюнча салыштыруу колдонулат.', 'zh-Hant': '神經網路模型：無法使用（{e}）— 改用舊的特徵比對。' },
