  photo_second_voice: { bg: 'Снимката е втори глас — водят областта, болката и оплакванията.', ru: 'Фото — второй голос; ведут область, боль и жалобы.', uk: 'Фото — другий голос; ведуть ділянка, біль і скарги.', en: 'The photo is a second opinion — the area, pain and complaints lead.', de: 'Das Foto ist eine zweite Stimme — Bereich, Schmerz und Beschwerden führen.', fr: 'La photo est un second avis — la zone, la douleur et les plaintes priment.', es: 'La foto es una segunda voz — mandan la zona, el dolor y las molestias.', 'es-MX': 'La foto es una segunda voz — mandan la zona, el dolor y las molestias.', it: 'La foto è una seconda voce — guidano la zona, il dolore e i disturbi.', pt: 'A foto é uma segunda voz — mandam a zona, a dor e as queixas.', ar: 'الصورة رأي ثانٍ — المنطقة والألم والشكاوى هي الأساس.', hi: 'फ़ोटो दूसरी राय है — क्षेत्र, दर्द और शिकायतें प्रमुख हैं।', ja: '写真は二番目の判断材料です — 部位・痛み・症状を優先します。', ky: 'Сүрөт экинчи добуш — аймак, оору жана даттануулар жетектейт.', 'zh-Hant': '照片是第二意見 — 以部位、疼痛與主訴為主。' },
  photo_nn_unsure: { bg: 'Приликата не е ясна — водят признаците.', ru: 'Сходство неявное — ведут признаки.', uk: 'Схожість нечітка — ведуть ознаки.', en: 'The resemblance is not clear — the symptoms lead.', de: 'Die Ähnlichkeit ist nicht eindeutig — die Symptome führen.', fr: 'La ressemblance n’est pas nette — les symptômes priment.', es: 'El parecido no es claro — mandan los síntomas.', 'es-MX': 'El parecido no es claro — mandan los síntomas.', it: 'La somiglianza non è chiara — guidano i sintomi.', pt: 'A semelhança não é clara — mandam os sintomas.', ar: 'التشابه غير واضح — الأعراض هي الأساس.', hi: 'समानता स्पष्ट नहीं — लक्षण प्रमुख हैं।', ja: '類似は明確ではありません — 症状を優先します。', ky: 'Окшоштук так эмес — белгилер жетектейт.', 'zh-Hant': '相似度不明確 — 以症狀為主。' },
