for (const k in S_MORE) { if (S[k]) Object.assign(S[k], S_MORE[k]); }
for (const k in COND_MORE) { if (COND_NAMES[k]) Object.assign(COND_NAMES[k], COND_MORE[k]); }
export function condName(id) {
  const row = COND_NAMES[id]; if (!row) return id;
  const lang = getLang();
  return row[lang] || row[String(lang).split('-')[0]] || row.en || row.bg || id;
}

export function D(key) {
  const row = S[key]; if (!row) return key;
  const lang = getLang();
  return row[lang] || row[String(lang).split('-')[0]] || row.en || row.bg || key;
}
// Етикет от опция за текущия език.
export function optLabel(opt) {
  const lang = getLang(), base = String(lang).split('-')[0], more = OPT_MORE[opt.en] || {};
  return opt[lang] || more[lang] || opt[base] || more[base] || opt.en || opt.bg || opt.v;
}
// Надпис с подстановки: Df('corpus_loading', { n: 1, m: 4 }) → „…част 1 от 4…".
export function Df(key, vars) {
  let s = D(key); vars = vars || {};
  for (const k in vars) s = s.split('{' + k + '}').join(String(vars[k]));
  return s;
}
